window.kbPageData["views/entry/k-68ef744b0f1f4ba4"] = {"key":"entry/k-68ef744b0f1f4ba4","state":{"route":"entry/k-68ef744b0f1f4ba4"},"node":{"id":"k-68ef744b0f1f4ba4","mode":"k","title":"增长率与比重","type":"概念与词义","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["增长率与比重的统计口径"],"qs":["江苏 2025 A类 行测#92"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"增长率是某项数量相对基期同类数量的变动比例。比重是同一时期部分量占整体量的比例。","review":{"definition":"增长率是某项数量相对基期同类数量的变动比例。比重是同一时期部分量占整体量的比例。","explanation":"第92题中，甲以折叠屏手机销量连续多年保持两位数增长为据，判断它将成为研发风口。乙用折叠屏手机仅占同期手机总销量1.6%来质疑投入价值。销量增长快与销量占比低可以同时成立。C项采用相似的论证方式，甲根据错别字检出量增加主张增员，乙指出出版总量也增加，而错别字检出率维持在万分之一左右，据此质疑增员的必要性。两段对话都是甲根据某项数量上升提出判断，乙用该数量在相应整体中的低比重来质疑结论。","references":[],"evidence":"折叠屏手机经历多年发展仍只占手机整体销量的1.6%","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 A类 行测#92":{"paper":"江苏 2025 A类 行测","n":92,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",19],"asrc":["4fe8e0544dd7b47699d2.pdf",29],"card":"c50bad3725bd889ab4b27bdd","links":[{"id":"k-68ef744b0f1f4ba4","role":"解题依据","why":"增长率以基期的同类数量为分母，比重以同期的整体数量为分母，因而增长较快可以与比重较低同时成立。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-68ef744b0f1f4ba4":[["江苏 2025 A类 行测#92"]]}};
